# ruff: noqa: E501
"""Preserve exact definition source copies and atomic mixed-Run compensation.

The predecessor body is frozen from the actual s0_0754 catalog. Existing
function ACLs and all existing policies are retained unchanged.
"""

PREDECESSOR_EVIDENCE_LINK_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_link_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; actual_link_run agent_runs; p proposals; i proposal_items; k category_knowledge_entries;\n target_link_spec definition_specs; def definition_revisions; root jsonb; shared boolean; target_product uuid; target_proposal uuid;\nBEGIN\n IF TG_OP='UPDATE' THEN\n  SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.reverted_by_receipt_id;\n  IF r.category_id<>NEW.category_id OR r.actor_id<>r.requester_id OR r.actor_id IS DISTINCT FROM scope_actor()\n   OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n   OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n      (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n   OR NOT ( (r.operation='evidence.claim.withdraw' AND NEW.evidence_type='claim' AND r.subject_id=NEW.evidence_id\n     AND EXISTS(SELECT 1 FROM claim_withdrawals w WHERE w.tenant_id=NEW.tenant_id AND w.receipt_id=r.id AND w.claim_id=NEW.evidence_id))\n    OR (r.operation='ai.run.revert' AND r.subject_type='agent_run' AND r.subject_id=NEW.run_id AND NEW.origin='ai_draft'\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id AND ar.requester_id=r.requester_id AND ar.revert_receipt_id=r.id AND ar.reverted_by=r.requester_id)))\n   OR EXISTS(SELECT 1 FROM proposal_decisions d JOIN proposal_submissions sub ON sub.tenant_id=d.tenant_id AND sub.id=d.submission_id\n    WHERE d.tenant_id=NEW.tenant_id AND d.category_id=NEW.category_id AND position(NEW.id::text IN sub.frozen_document::text)>0)\n   OR EXISTS(SELECT 1 FROM definition_specs s JOIN definition_revisions d ON d.tenant_id=s.tenant_id AND d.id=s.definition_id\n    WHERE s.tenant_id=NEW.tenant_id AND s.category_id=NEW.category_id AND d.sealed AND position(NEW.id::text IN s.source_refs::text)>0) THEN\n   RAISE EXCEPTION 'evidence link revert proof or consumption mismatch' USING ERRCODE='23514'; END IF;\n  IF r.operation='ai.run.revert' THEN\n   PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n   IF NOT EXISTS(SELECT 1 FROM action_receipts original JOIN agent_runs actual ON actual.tenant_id=original.tenant_id AND actual.id=original.agent_run_id\n     WHERE original.tenant_id=NEW.tenant_id AND original.id=NEW.receipt_id AND original.agent_run_id=NEW.run_id\n      AND original.operation='evidence.link.create' AND original.subject_type='evidence_link' AND original.subject_id=NEW.id\n      AND original.category_id=NEW.category_id AND original.actor_id=actual.writer_id AND original.requester_id=r.requester_id\n      AND actual.category_id=NEW.category_id AND actual.writer_id=NEW.writer_id AND actual.requester_id=r.requester_id)\n    OR (NEW.target_type='proposal_item' AND NOT EXISTS(SELECT 1 FROM proposal_items item JOIN proposals proposal\n     ON proposal.tenant_id=item.tenant_id AND proposal.id=item.proposal_id WHERE item.tenant_id=NEW.tenant_id AND item.id=NEW.target_id\n      AND NOT item.removed AND item.current_version=NEW.target_version AND proposal.owner_id=r.requester_id AND proposal.status IN ('draft','returned')))\n    OR (NEW.target_type='knowledge_entry' AND NOT EXISTS(SELECT 1 FROM category_knowledge_entries entry WHERE entry.tenant_id=NEW.tenant_id\n     AND entry.id=NEW.target_id AND entry.version=NEW.target_version AND EXISTS(SELECT 1 FROM category_knowledge_current current\n      WHERE current.tenant_id=entry.tenant_id AND current.category_id=entry.category_id AND current.current_entry_id=entry.id AND current.status='active')))\n    OR (NEW.target_type='definition_spec' AND NOT EXISTS(SELECT 1 FROM definition_specs spec JOIN definition_revisions definition\n     ON definition.tenant_id=spec.tenant_id AND definition.id=spec.definition_id WHERE spec.tenant_id=NEW.tenant_id AND spec.id=NEW.target_id\n      AND definition.revision=NEW.target_version AND NOT definition.sealed AND definition.status='draft' AND EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=spec.tenant_id AND current.definition_id=spec.definition_id AND current.item_id=spec.item_id AND current.current_row_id=spec.id AND current.current_version=spec.item_version AND NOT current.removed))) THEN\n    RAISE EXCEPTION 'evidence link run revert target changed' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF r.operation='ai.run.revert' AND NEW.target_type='proposal_item' THEN\n   SELECT pp.* INTO STRICT p FROM proposals pp JOIN proposal_items ii ON ii.tenant_id=pp.tenant_id AND ii.proposal_id=pp.id\n    WHERE ii.tenant_id=NEW.tenant_id AND ii.id=NEW.target_id FOR UPDATE OF pp;\n   DELETE FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id;\n   INSERT INTO proposal_sources(id,tenant_id,category_id,proposal_id,source_type,source_id,source_version,privacy,ref_count,created_at)\n   SELECT gen_random_uuid(),NEW.tenant_id,NEW.category_id,p.id,source_type,source_id,source_version,privacy,ref_count,statement_timestamp()\n    FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id);\n   UPDATE proposals SET private_source_count=(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private'),\n    effective_visibility=CASE WHEN EXISTS(SELECT 1 FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private') THEN 'private' ELSE visibility END,\n    context_hint=true WHERE tenant_id=NEW.tenant_id AND id=p.id;\n  END IF;\n  RETURN NULL;\n END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n root=m3_evidence_root(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id,NEW.evidence_version);\n IF NEW.evidence_type='claim' THEN\n  IF NOT m3_claim_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_id) THEN RAISE EXCEPTION 'claim unreadable' USING ERRCODE='23514'; END IF;\n ELSIF NOT m3_evidence_source_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id) THEN\n  RAISE EXCEPTION 'link source unreadable' USING ERRCODE='23514';\n END IF;\n IF NOT m3_evidence_target_reader(NEW.tenant_id,NEW.category_id,NEW.target_type,NEW.target_id)\n  OR NOT category_access(NEW.tenant_id,NEW.category_id,true) THEN RAISE EXCEPTION 'link target unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  SELECT * INTO STRICT i FROM proposal_items WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=i.proposal_id;\n  IF i.current_version<>NEW.target_version OR i.removed OR p.status NOT IN ('draft','returned') OR p.owner_id<>r.requester_id THEN\n   RAISE EXCEPTION 'link proposal target mismatch' USING ERRCODE='23514'; END IF;\n  target_proposal=p.id; shared=p.effective_visibility<>'private';\n ELSIF NEW.target_type='knowledge_entry' THEN\n  SELECT * INTO STRICT k FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  IF k.version<>NEW.target_version OR NOT EXISTS(SELECT 1 FROM category_knowledge_current cur WHERE cur.tenant_id=k.tenant_id\n   AND cur.category_id=k.category_id AND cur.current_entry_id=k.id AND cur.status='active') THEN\n   RAISE EXCEPTION 'link knowledge target mismatch' USING ERRCODE='23514'; END IF;\n  shared=true;\n ELSE\n  SELECT * INTO STRICT target_link_spec FROM definition_specs WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT def FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=target_link_spec.definition_id FOR UPDATE;\n  IF def.sealed OR def.status<>'draft' OR def.revision<>NEW.target_version\n   OR NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=target_link_spec.tenant_id\n    AND current.definition_id=target_link_spec.definition_id AND current.item_id=target_link_spec.item_id\n    AND current.current_row_id=target_link_spec.id AND current.current_version=target_link_spec.item_version AND NOT current.removed) THEN\n   RAISE EXCEPTION 'link sealed definition target mismatch' USING ERRCODE='23514'; END IF;\n  target_product=def.product_id;\n  shared=def.visibility<>'private' AND EXISTS(SELECT 1 FROM products pr WHERE pr.tenant_id=def.tenant_id AND pr.id=def.product_id AND pr.visibility<>'private');\n END IF;\n IF (shared AND ((root->>'private')::boolean OR coalesce((root->>'claim_private')::boolean,false)))\n  OR (coalesce((root->>'claim_private')::boolean,false) AND (root->>'proposal_id')::uuid IS DISTINCT FROM target_proposal) THEN\n  RAISE EXCEPTION 'private evidence cannot enter shared target' USING ERRCODE='23514'; END IF;\n IF r.operation<>'evidence.link.create' OR r.subject_type<>'evidence_link' OR r.subject_id<>NEW.id OR r.subject_revision<>1\n  OR r.category_id<>NEW.category_id OR r.product_id IS DISTINCT FROM target_product OR r.actor_id IS DISTINCT FROM scope_actor()\n  OR r.requester_id IS DISTINCT FROM scope_requester() OR r.agent_run_id IS DISTINCT FROM NEW.run_id\n  OR NEW.confirmed_by IS NOT NULL OR r.run_id IS NOT NULL OR r.confirmation_id IS NOT NULL\n  OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n     (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence link receipt mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.origin='human' THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id OR NEW.run_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals pr WHERE pr.tenant_id=NEW.tenant_id AND pr.id=NEW.writer_id AND pr.kind='human' AND pr.active) THEN\n   RAISE EXCEPTION 'evidence link human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_link_run FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF actual_link_run.category_id<>NEW.category_id OR actual_link_run.product_id IS DISTINCT FROM target_product OR actual_link_run.writer_id<>NEW.writer_id\n   OR actual_link_run.requester_id<>r.requester_id OR actual_link_run.writer_id<>r.actor_id OR actual_link_run.reverted_at IS NOT NULL OR actual_link_run.state='cancelled'\n   OR (target_proposal IS NOT NULL AND actual_link_run.proposal_id IS DISTINCT FROM target_proposal)\n   OR (target_proposal IS NULL AND actual_link_run.private_context)\n   OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id AND tc.run_id=NEW.run_id\n    AND tc.receipt_id=r.id AND tc.state='completed' AND tc.execution_binding->>'operation'=r.operation) THEN\n   RAISE EXCEPTION 'evidence link T0 provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'evidence link imported path unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  IF NOT EXISTS(SELECT 1 FROM proposal_revisions document_revision\n    JOIN action_receipts actual_receipt ON actual_receipt.tenant_id=document_revision.tenant_id AND actual_receipt.id=document_revision.receipt_id\n    JOIN proposals current_proposal ON current_proposal.tenant_id=document_revision.tenant_id AND current_proposal.id=document_revision.proposal_id\n    JOIN evidence_links actual_link ON actual_link.tenant_id=actual_receipt.tenant_id AND actual_link.id=actual_receipt.subject_id\n    WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.category_id=NEW.category_id\n     AND document_revision.proposal_id=p.id AND document_revision.receipt_id=r.id\n     AND document_revision.revision=current_proposal.revision AND document_revision.changed_items='[]'::jsonb\n     AND document_revision.actor_id=r.actor_id AND document_revision.run_id IS NOT DISTINCT FROM r.agent_run_id\n     AND actual_link.id=NEW.id AND actual_link.receipt_id=r.id\n     AND document_revision.xmin=actual_receipt.xmin AND current_proposal.xmin=actual_receipt.xmin AND actual_link.xmin=actual_receipt.xmin\n     AND EXISTS(SELECT 1 FROM proposal_revisions prior WHERE prior.tenant_id=document_revision.tenant_id\n      AND prior.proposal_id=document_revision.proposal_id AND prior.revision=document_revision.revision-1))\n   OR (SELECT count(*) FROM proposal_revisions document_revision WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.receipt_id=r.id)<>1\n   OR p.private_source_count<>(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private')\n   OR p.effective_visibility IS DISTINCT FROM (CASE WHEN p.private_source_count>0 THEN 'private' ELSE p.visibility END)\n   OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id)\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id)\n     UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id))) THEN\n   RAISE EXCEPTION 'evidence link missing proposal revision or projection' USING ERRCODE='23514'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n"

EVIDENCE_LINK_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_link_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; actual_link_run agent_runs; p proposals; i proposal_items; k category_knowledge_entries;\n target_link_spec definition_specs; def definition_revisions; root jsonb; shared boolean; target_product uuid; target_proposal uuid;\nBEGIN\n IF TG_OP='UPDATE' THEN\n  SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.reverted_by_receipt_id;\n  IF r.category_id<>NEW.category_id OR r.actor_id<>r.requester_id OR r.actor_id IS DISTINCT FROM scope_actor()\n   OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n   OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n      (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n   OR NOT ( (r.operation='evidence.claim.withdraw' AND NEW.evidence_type='claim' AND r.subject_id=NEW.evidence_id\n     AND EXISTS(SELECT 1 FROM claim_withdrawals w WHERE w.tenant_id=NEW.tenant_id AND w.receipt_id=r.id AND w.claim_id=NEW.evidence_id))\n    OR (r.operation='ai.run.revert' AND r.subject_type='agent_run' AND r.subject_id=NEW.run_id AND NEW.origin='ai_draft'\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id AND ar.requester_id=r.requester_id AND ar.revert_receipt_id=r.id AND ar.reverted_by=r.requester_id)))\n   OR EXISTS(SELECT 1 FROM proposal_decisions d JOIN proposal_submissions sub ON sub.tenant_id=d.tenant_id AND sub.id=d.submission_id\n    WHERE d.tenant_id=NEW.tenant_id AND d.category_id=NEW.category_id AND position(NEW.id::text IN sub.frozen_document::text)>0)\n   OR EXISTS(SELECT 1 FROM definition_specs s JOIN definition_revisions d ON d.tenant_id=s.tenant_id AND d.id=s.definition_id\n    WHERE s.tenant_id=NEW.tenant_id AND s.category_id=NEW.category_id AND d.sealed AND position(NEW.id::text IN s.source_refs::text)>0) THEN\n   RAISE EXCEPTION 'evidence link revert proof or consumption mismatch' USING ERRCODE='23514'; END IF;\n  IF r.operation='ai.run.revert' THEN\n   PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n   IF NOT EXISTS(SELECT 1 FROM action_receipts original JOIN agent_runs actual ON actual.tenant_id=original.tenant_id AND actual.id=original.agent_run_id\n     WHERE original.tenant_id=NEW.tenant_id AND original.id=NEW.receipt_id AND original.agent_run_id=NEW.run_id\n      AND original.operation='evidence.link.create' AND original.subject_type='evidence_link' AND original.subject_id=NEW.id\n      AND original.category_id=NEW.category_id AND original.actor_id=actual.writer_id AND original.requester_id=r.requester_id\n      AND actual.category_id=NEW.category_id AND actual.writer_id=NEW.writer_id AND actual.requester_id=r.requester_id)\n    OR (NEW.target_type='proposal_item' AND NOT EXISTS(SELECT 1 FROM proposal_items item JOIN proposals proposal\n     ON proposal.tenant_id=item.tenant_id AND proposal.id=item.proposal_id WHERE item.tenant_id=NEW.tenant_id AND item.id=NEW.target_id\n      AND NOT item.removed AND item.current_version=NEW.target_version AND proposal.owner_id=r.requester_id AND proposal.status IN ('draft','returned')))\n    OR (NEW.target_type='knowledge_entry' AND NOT EXISTS(SELECT 1 FROM category_knowledge_entries entry WHERE entry.tenant_id=NEW.tenant_id\n     AND entry.id=NEW.target_id AND entry.version=NEW.target_version AND EXISTS(SELECT 1 FROM category_knowledge_current current\n      WHERE current.tenant_id=entry.tenant_id AND current.category_id=entry.category_id AND current.current_entry_id=entry.id AND current.status='active')))\n    OR (NEW.target_type='definition_spec' AND NOT EXISTS(SELECT 1 FROM definition_specs spec JOIN definition_revisions definition\n     ON definition.tenant_id=spec.tenant_id AND definition.id=spec.definition_id WHERE spec.tenant_id=NEW.tenant_id AND spec.id=NEW.target_id\n      AND definition.revision=NEW.target_version AND NOT definition.sealed AND definition.status='draft' AND (\n       EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=spec.tenant_id AND current.definition_id=spec.definition_id AND current.item_id=spec.item_id AND current.current_row_id=spec.id AND current.current_version=spec.item_version AND NOT current.removed)\n       OR EXISTS(SELECT 1 FROM definition_spec_current current\n        JOIN definition_specs compensation ON compensation.tenant_id=current.tenant_id\n         AND compensation.category_id=current.category_id AND compensation.product_id=current.product_id\n         AND compensation.definition_id=current.definition_id AND compensation.item_id=current.item_id\n         AND compensation.id=current.current_row_id AND compensation.item_version=current.current_version\n         AND compensation.removed=current.removed\n        JOIN action_receipts source_receipt ON source_receipt.tenant_id=spec.tenant_id\n         AND source_receipt.id=spec.receipt_id\n        JOIN action_receipts compensation_receipt ON compensation_receipt.tenant_id=compensation.tenant_id\n         AND compensation_receipt.id=compensation.receipt_id\n        WHERE current.tenant_id=spec.tenant_id AND current.category_id=spec.category_id\n         AND current.product_id=spec.product_id AND current.definition_id=spec.definition_id\n         AND current.item_id=spec.item_id AND compensation.item_version>spec.item_version\n         AND spec.run_id=NEW.run_id AND source_receipt.agent_run_id=NEW.run_id\n         AND source_receipt.operation='product.definition.item.patch'\n         AND source_receipt.subject_type='definition_revision' AND source_receipt.subject_id=spec.definition_id\n         AND source_receipt.category_id=spec.category_id AND source_receipt.product_id=spec.product_id\n         AND compensation_receipt.id=r.id AND compensation_receipt.operation='ai.run.revert'\n         AND compensation_receipt.subject_type='agent_run' AND compensation_receipt.subject_id=NEW.run_id\n         AND compensation_receipt.category_id=spec.category_id AND compensation_receipt.product_id=spec.product_id\n         AND compensation.xmin=compensation_receipt.xmin\n         AND current.xmin=compensation_receipt.xmin)\n      ))) THEN\n    RAISE EXCEPTION 'evidence link run revert target changed' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF r.operation='ai.run.revert' AND NEW.target_type='proposal_item' THEN\n   SELECT pp.* INTO STRICT p FROM proposals pp JOIN proposal_items ii ON ii.tenant_id=pp.tenant_id AND ii.proposal_id=pp.id\n    WHERE ii.tenant_id=NEW.tenant_id AND ii.id=NEW.target_id FOR UPDATE OF pp;\n   DELETE FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id;\n   INSERT INTO proposal_sources(id,tenant_id,category_id,proposal_id,source_type,source_id,source_version,privacy,ref_count,created_at)\n   SELECT gen_random_uuid(),NEW.tenant_id,NEW.category_id,p.id,source_type,source_id,source_version,privacy,ref_count,statement_timestamp()\n    FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id);\n   UPDATE proposals SET private_source_count=(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private'),\n    effective_visibility=CASE WHEN EXISTS(SELECT 1 FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private') THEN 'private' ELSE visibility END,\n    context_hint=true WHERE tenant_id=NEW.tenant_id AND id=p.id;\n  END IF;\n  RETURN NULL;\n END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n root=m3_evidence_root(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id,NEW.evidence_version);\n IF NEW.evidence_type='claim' THEN\n  IF NOT m3_claim_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_id) THEN RAISE EXCEPTION 'claim unreadable' USING ERRCODE='23514'; END IF;\n ELSIF NOT m3_evidence_source_reader(NEW.tenant_id,NEW.category_id,NEW.evidence_type,NEW.evidence_id) THEN\n  RAISE EXCEPTION 'link source unreadable' USING ERRCODE='23514';\n END IF;\n IF NOT m3_evidence_target_reader(NEW.tenant_id,NEW.category_id,NEW.target_type,NEW.target_id)\n  OR NOT category_access(NEW.tenant_id,NEW.category_id,true) THEN RAISE EXCEPTION 'link target unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  SELECT * INTO STRICT i FROM proposal_items WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=i.proposal_id;\n  IF i.current_version<>NEW.target_version OR i.removed OR p.status NOT IN ('draft','returned') OR p.owner_id<>r.requester_id THEN\n   RAISE EXCEPTION 'link proposal target mismatch' USING ERRCODE='23514'; END IF;\n  target_proposal=p.id; shared=p.effective_visibility<>'private';\n ELSIF NEW.target_type='knowledge_entry' THEN\n  SELECT * INTO STRICT k FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  IF k.version<>NEW.target_version OR NOT EXISTS(SELECT 1 FROM category_knowledge_current cur WHERE cur.tenant_id=k.tenant_id\n   AND cur.category_id=k.category_id AND cur.current_entry_id=k.id AND cur.status='active') THEN\n   RAISE EXCEPTION 'link knowledge target mismatch' USING ERRCODE='23514'; END IF;\n  shared=true;\n ELSE\n  SELECT * INTO STRICT target_link_spec FROM definition_specs WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=NEW.target_id;\n  SELECT * INTO STRICT def FROM definition_revisions WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND id=target_link_spec.definition_id FOR UPDATE;\n  IF def.sealed OR def.status<>'draft' OR def.revision<>NEW.target_version\n   OR NOT EXISTS(SELECT 1 FROM definition_spec_current current WHERE current.tenant_id=target_link_spec.tenant_id\n    AND current.definition_id=target_link_spec.definition_id AND current.item_id=target_link_spec.item_id\n    AND current.current_row_id=target_link_spec.id AND current.current_version=target_link_spec.item_version AND NOT current.removed) THEN\n   RAISE EXCEPTION 'link sealed definition target mismatch' USING ERRCODE='23514'; END IF;\n  target_product=def.product_id;\n  shared=def.visibility<>'private' AND EXISTS(SELECT 1 FROM products pr WHERE pr.tenant_id=def.tenant_id AND pr.id=def.product_id AND pr.visibility<>'private');\n END IF;\n IF (shared AND ((root->>'private')::boolean OR coalesce((root->>'claim_private')::boolean,false)))\n  OR (coalesce((root->>'claim_private')::boolean,false) AND (root->>'proposal_id')::uuid IS DISTINCT FROM target_proposal) THEN\n  RAISE EXCEPTION 'private evidence cannot enter shared target' USING ERRCODE='23514'; END IF;\n IF r.operation<>'evidence.link.create' OR r.subject_type<>'evidence_link' OR r.subject_id<>NEW.id OR r.subject_revision<>1\n  OR r.category_id<>NEW.category_id OR r.product_id IS DISTINCT FROM target_product OR r.actor_id IS DISTINCT FROM scope_actor()\n  OR r.requester_id IS DISTINCT FROM scope_requester() OR r.agent_run_id IS DISTINCT FROM NEW.run_id\n  OR NEW.confirmed_by IS NOT NULL OR r.run_id IS NOT NULL OR r.confirmation_id IS NOT NULL\n  OR (SELECT xmin FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id) IS DISTINCT FROM\n     (SELECT xmin FROM evidence_links WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence link receipt mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.origin='human' THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id OR NEW.run_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals pr WHERE pr.tenant_id=NEW.tenant_id AND pr.id=NEW.writer_id AND pr.kind='human' AND pr.active) THEN\n   RAISE EXCEPTION 'evidence link human provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT actual_link_run FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF actual_link_run.category_id<>NEW.category_id OR actual_link_run.product_id IS DISTINCT FROM target_product OR actual_link_run.writer_id<>NEW.writer_id\n   OR actual_link_run.requester_id<>r.requester_id OR actual_link_run.writer_id<>r.actor_id OR actual_link_run.reverted_at IS NOT NULL OR actual_link_run.state='cancelled'\n   OR (target_proposal IS NOT NULL AND actual_link_run.proposal_id IS DISTINCT FROM target_proposal)\n   OR (target_proposal IS NULL AND actual_link_run.private_context)\n   OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id AND tc.run_id=NEW.run_id\n    AND tc.receipt_id=r.id AND tc.state='completed' AND tc.execution_binding->>'operation'=r.operation) THEN\n   RAISE EXCEPTION 'evidence link T0 provenance mismatch' USING ERRCODE='23514'; END IF;\n ELSE RAISE EXCEPTION 'evidence link imported path unavailable' USING ERRCODE='23514'; END IF;\n IF NEW.target_type='proposal_item' THEN\n  IF NOT EXISTS(SELECT 1 FROM proposal_revisions document_revision\n    JOIN action_receipts actual_receipt ON actual_receipt.tenant_id=document_revision.tenant_id AND actual_receipt.id=document_revision.receipt_id\n    JOIN proposals current_proposal ON current_proposal.tenant_id=document_revision.tenant_id AND current_proposal.id=document_revision.proposal_id\n    JOIN evidence_links actual_link ON actual_link.tenant_id=actual_receipt.tenant_id AND actual_link.id=actual_receipt.subject_id\n    WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.category_id=NEW.category_id\n     AND document_revision.proposal_id=p.id AND document_revision.receipt_id=r.id\n     AND document_revision.revision=current_proposal.revision AND document_revision.changed_items='[]'::jsonb\n     AND document_revision.actor_id=r.actor_id AND document_revision.run_id IS NOT DISTINCT FROM r.agent_run_id\n     AND actual_link.id=NEW.id AND actual_link.receipt_id=r.id\n     AND document_revision.xmin=actual_receipt.xmin AND current_proposal.xmin=actual_receipt.xmin AND actual_link.xmin=actual_receipt.xmin\n     AND EXISTS(SELECT 1 FROM proposal_revisions prior WHERE prior.tenant_id=document_revision.tenant_id\n      AND prior.proposal_id=document_revision.proposal_id AND prior.revision=document_revision.revision-1))\n   OR (SELECT count(*) FROM proposal_revisions document_revision WHERE document_revision.tenant_id=NEW.tenant_id AND document_revision.receipt_id=r.id)<>1\n   OR p.private_source_count<>(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy='private')\n   OR p.effective_visibility IS DISTINCT FROM (CASE WHEN p.private_source_count>0 THEN 'private' ELSE p.visibility END)\n   OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id)\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id)\n     UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id))) THEN\n   RAISE EXCEPTION 'evidence link missing proposal revision or projection' USING ERRCODE='23514'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n"

INHERITED_SOURCE_VISIBLE = """
CREATE FUNCTION public.m3_definition_inherited_source_insert_visible(
 t uuid,c uuid,p uuid,d uuid,sid uuid,ver integer,line_no integer,quote_text text,source_keys jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog','public','pg_temp'
AS $function$
 SELECT category_access(t,c,true) AND scope_actor()=scope_requester()
  AND EXISTS(SELECT 1 FROM principals actor WHERE actor.tenant_id=t
   AND actor.id=scope_actor() AND actor.kind='human' AND actor.active)
  AND EXISTS(SELECT 1 FROM definition_revisions child
   JOIN products product ON product.tenant_id=child.tenant_id AND product.category_id=child.category_id
    AND product.id=child.product_id
   JOIN definition_sources source ON source.tenant_id=child.tenant_id AND source.category_id=child.category_id
    AND source.product_id=child.product_id AND source.definition_id=child.parent_definition_id
   JOIN artifact_versions artifact ON artifact.tenant_id=source.tenant_id AND artifact.category_id=source.category_id
    AND artifact.id=source.artifact_id
   WHERE child.tenant_id=t AND child.category_id=c AND child.product_id=p AND child.id=d
    AND child.owner_id=scope_requester()
    AND source.artifact_id=sid AND source.source_revision=ver
    AND source.line=line_no AND source.quote=quote_text AND source.spec_keys IS NOT DISTINCT FROM source_keys
    AND (artifact.original_id IS NULL OR EXISTS(SELECT 1 FROM original_security security
     WHERE security.tenant_id=t AND security.category_id=c AND security.original_id=artifact.original_id
      AND security.source_state='active' AND security.disposition='active'))
    AND source_object_audience(t,c,'products',product.id,product.owner_id,product.visibility))
  AND m3_definition_inherited_source_proven(t,c,p,d,sid,ver,line_no,quote_text)
$function$;
REVOKE ALL ON FUNCTION public.m3_definition_inherited_source_insert_visible(uuid,uuid,uuid,uuid,uuid,integer,integer,text,jsonb)
 FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch;
GRANT EXECUTE ON FUNCTION public.m3_definition_inherited_source_insert_visible(uuid,uuid,uuid,uuid,uuid,integer,integer,text,jsonb)
 TO pdos_next_app;
"""

